constexpr int CNU_EDGE_GROUPS = (NUM_DETECTORS + CNU_PARALLEL - 1) / CNU_PARALLEL;
constexpr int VNU_EDGE_GROUPS = NUM_FAULT_WORDS * (PACK_BITS / VNU_PARALLEL);
constexpr int DET_EDGE_GROUPS = (NUM_DETECTORS + CONVERGENCE_PARALLEL - 1) / CONVERGENCE_PARALLEL;
constexpr int EDGE_BANK_PORTS = 2;
constexpr int DET_BANK_PORTS = 2;
static_assert(EDGE_BANK_PORTS == 2, "message banks require dual-port scheduling");
static_assert(DET_BANK_PORTS == 2, "detector banks require dual-port scheduling");
static_assert(NUM_ACTIVE_FAULTS > 0, "NUM_ACTIVE_FAULTS must be positive");
static_assert(NUM_ACTIVE_FAULTS <= NUM_FAULTS,
              "NUM_ACTIVE_FAULTS must not exceed NUM_FAULTS");
static_assert(CNU_EDGE_GROUPS == (NUM_DETECTORS + CNU_PARALLEL - 1) / CNU_PARALLEL,
              "CNU_EDGE_GROUPS must match NUM_DETECTORS/CNU_PARALLEL");
static_assert(VNU_EDGE_GROUPS == NUM_FAULT_WORDS * (PACK_BITS / VNU_PARALLEL),
              "VNU_EDGE_GROUPS must match packed VNU grouping");
static_assert(DET_EDGE_GROUPS == (NUM_DETECTORS + CONVERGENCE_PARALLEL - 1) / CONVERGENCE_PARALLEL,
              "DET_EDGE_GROUPS must match NUM_DETECTORS/CONVERGENCE_PARALLEL");

